import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"震","description":"焦氏易林注 - 震","frontmatter":{"title":"震","description":"焦氏易林注 - 震"},"headers":[],"relativePath":"classics/jiaoyilin/051.md","filePath":"classics/jiaoyilin/051.md"}'),l={name:"classics/jiaoyilin/051.md"};function n(d,a,t,s,o,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="震" tabindex="-1">震 <a class="header-anchor" href="#震" aria-label="Permalink to “震”">​</a></h1><h3 id="震-1" tabindex="-1">震 <a class="header-anchor" href="#震-1" aria-label="Permalink to “震”">​</a></h3><h3 id="震之乾" tabindex="-1">震之乾 <a class="header-anchor" href="#震之乾" aria-label="Permalink to “震之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>陷塗溺水，火燒我履，憂患重累。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦《震》象。震為大塗，坎為水、為陷溺，互艮為火，震在艮上，故曰火燒我履。坎為憂患。</p><h3 id="震之坤" tabindex="-1">震之坤 <a class="header-anchor" href="#震之坤" aria-label="Permalink to “震之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>旦生夕死，名曰嬰鬼，不可得祀。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《升》。祀，宋元本訛視。</p><h3 id="震之屯" tabindex="-1">震之屯 <a class="header-anchor" href="#震之屯" aria-label="Permalink to “震之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>揚水潛，使石潔白。裡素表朱，遊戲皋沃。得其所願，心志娛樂。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《師》。○石，宋元本作君，表朱作附珠，均依汲古。沃，元本訛●，汲古作澤，其作君，依宋元本。裡，各本皆作衣，依《豫》之《大過》宋元本校。</p><h3 id="震之蒙" tabindex="-1">震之蒙 <a class="header-anchor" href="#震之蒙" aria-label="Permalink to “震之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>眾鳥所翔，中有大怪。九身無頭，魂驚魄去，不可以居。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《同人》。</p><h3 id="震之需" tabindex="-1">震之需 <a class="header-anchor" href="#震之需" aria-label="Permalink to “震之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>刖根枯株，不生肌膚。病在於心，日以焦枯。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>此亦用震象。伏巽，下斷，故曰別根。巽殞落，故曰枯株。艮為肌膚，本卦伏坤為死，故曰不生。坎為心病，離為日、為焦枯。</p><h3 id="震之訟" tabindex="-1">震之訟 <a class="header-anchor" href="#震之訟" aria-label="Permalink to “震之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>府藏之富，王以振貸。捕魚河海，笀多得。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>詳《坎》之《大過》。○貸，汲古作貧。笀，元本作網，汲古作罟網，依宋本。</p><h3 id="震之師" tabindex="-1">震之師 <a class="header-anchor" href="#震之師" aria-label="Permalink to “震之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>一莖九纏，更相牽攣。宿明俯仰，不得東西。請讞當決，日午被刑。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>坎為莖，數一，故曰一莖。震數九，故曰九纏。伏巽為繩、為纏，遇卦震互艮為牽，初至四正反艮，故曰互相牽攣。震為旦，故曰宿明。宿明，即黎明也。震東，坎西，艮閉，故曰不得東西。震為請、為讞，坤殺，故曰當決、曰被刑。伏離，故曰日午被刑。《史記》司馬穰苴與監軍莊賈期旦日日中會於軍門，及期，賈不至，召軍正問曰：軍法期而後至者雲何，曰：當斬，乃斬之。○相，汲古作用，請作贊，均依宋元本。決，宋元本作報，午作中，均依汲古。</p><h3 id="震之比" tabindex="-1">震之比 <a class="header-anchor" href="#震之比" aria-label="Permalink to “震之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>耋老鮐背，齒牙動搖。近地遠天，下入黃泉。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>坤為老、為魚，艮為背，故曰鮐背。《詩大雅》黃耇臺背，《爾雅釋詁》老人皮膚消瘠，若駘魚也。伏兌為齒牙、為毀折，故曰勸搖。乾伏，故曰遠天。坤為水、為黃、為下、為死，故下入黃泉。</p><h3 id="震之小畜" tabindex="-1">震之小畜 <a class="header-anchor" href="#震之小畜" aria-label="Permalink to “震之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>羊舌叔虎，野心善怒。黷貨無厭，以滅其身。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>羊舌虎，叔向弟。襄二十二年以受賄為範宣子所殺。兌為羊、為口舌，伏艮為叔、為虎，故曰羊舌叔虎。坤為野、為心，震為怒，故曰野心善怒。坤為貨財、為身，坤殺，故曰以滅其身。○舌，汲古訛蛇，依宋元本。</p><h3 id="震之履" tabindex="-1">震之履 <a class="header-anchor" href="#震之履" aria-label="Permalink to “震之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>籲疑八子，更相欺紿。管叔善政，不見邪期。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>伏《豫》。震為子，坤卦數八，故曰八子。震為言，正反震，故曰更相欺紿。震為管，艮為叔，故曰客叔。坤為政，震為善，故曰善政。管叔者，管仲，言桓公死，諸公子為亂，管仲不及見也。○籲，宋元本作謀，依汲古。詩鄭風洵籲且樂，韓詩作恂盱，《爾雅釋詁》盱，憂也。然則籲疑者，憂疑也。</p><h3 id="震之泰" tabindex="-1">震之泰 <a class="header-anchor" href="#震之泰" aria-label="Permalink to “震之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>絆跳不遠，心與言反。尼丘顧家，茅簟朱華。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>震為跳，伏巽為繩，故曰絆跳。坤近，故曰不遠。坤為心，震為言，乾亦為言，震言與乾言相背，故曰言反。伏艮為尼丘、為家，巽為茅，兌為華，乾為大赤，故曰朱華。下二句義未祥，或有訛字。○絆，宋元本作伴，依汲古。跳，汲古作逃，逃跳古通。易林多古義。頗疑汲古是，今通俗從宋元本。</p><h3 id="震之否" tabindex="-1">震之否 <a class="header-anchor" href="#震之否" aria-label="Permalink to “震之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>蜉蝣戴盆，不能上山。搖推跌跋，頓傷其顏。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>巽為蟲，故曰蜉蝣。艮為戴、為盆，故曰蜉蝣戴盆。艮止，故不能上山。巽進退，故搖推跌跋。艮為顏，坤為傷。</p><h3 id="震之同人" tabindex="-1">震之同人 <a class="header-anchor" href="#震之同人" aria-label="Permalink to “震之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>朝露不久，為恩惠少。膏澤欲盡，咎在枯槁。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>通《師》。震為朝，坎為露，風散，故曰不久。震為恩惠，坎為膏澤，坤亡，故曰少、曰盡。離為枯槁。</p><h3 id="震之大有" tabindex="-1">震之大有 <a class="header-anchor" href="#震之大有" aria-label="Permalink to “震之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>河伯之功，九州島攸同。載祀六百，光烈無窮。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>此用《震》象。震為伯，互坎故曰河伯。互艮為州，震數九，重震，故曰九州島攸同。震為百，坎數六，故曰六百。離為光也。按：《竹書紀年》謂夏祀前後共四百七十一年，後儒疑之，茲謂九州島攸同，確謂禹也。載祀六百，謂禹食報之久也，較竹書更多。</p><h3 id="震之謙" tabindex="-1">震之謙 <a class="header-anchor" href="#震之謙" aria-label="Permalink to “震之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>三人北行，大見光明。道逢淑女，與我驥子。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>震為人，數三，故曰三人。坎為北，艮為光明、為道，坤女，震為淑，故曰道逢淑女。震為馬，故曰驥子。</p><h3 id="震之豫" tabindex="-1">震之豫 <a class="header-anchor" href="#震之豫" aria-label="Permalink to “震之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>金精躍怒，帶劍過午。徘徊高庫，宿於木下。兩虎相拒，弓弩滿野。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>詳《噬嗑》之《泰》。劍過，宋元本作釗通，依汲古。拒，汲古作距，依宋元本。○《河圖帝覽嬉》：月者，金之精，又虎亦為金精。艮為虎，兩虎相拒者，言正反艮相背也。高庫，地名，《呂氏春秋》出高庫之兵以賦民，《越絕書》高庫在安成裡，勾踐藏兵之所。</p><h3 id="震之隨" tabindex="-1">震之隨 <a class="header-anchor" href="#震之隨" aria-label="Permalink to “震之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>江河淮海，天之奧府。眾利所聚，可以富有。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>樂我君子，百福是受。詳《乾》之《觀》。五六句宋元本作好樂喜友，汲古作安樂無憂，依《乾》之《觀》校。</p><h3 id="震之蠱" tabindex="-1">震之蠱 <a class="header-anchor" href="#震之蠱" aria-label="Permalink to “震之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>不虞之患，禍至無門。奄忽暴卒，病傷我心。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《明夷》。</p><h3 id="震之臨" tabindex="-1">震之臨 <a class="header-anchor" href="#震之臨" aria-label="Permalink to “震之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>畫龍頭角，文章未成。甘言美語，說辭無名。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《噬嗑》。角，宋元本作頸，依汲古。</p><h3 id="震之觀" tabindex="-1">震之觀 <a class="header-anchor" href="#震之觀" aria-label="Permalink to “震之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>缺破不成，胎卵不生，不見兆形。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>詳《晉》之《益》。</p><h3 id="震之噬嗑" tabindex="-1">震之噬嗑 <a class="header-anchor" href="#震之噬嗑" aria-label="Permalink to “震之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>旁行不遠，三里復反。心多畏惡，日中止舍。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震為行，艮止，故不遠。艮為裡，震為反，數三，故曰三里復反。坎為心、為畏惡，離為日，艮為止、為舍。○復反，汲古作反覆，依宋元本。</p><h3 id="震之賁" tabindex="-1">震之賁 <a class="header-anchor" href="#震之賁" aria-label="Permalink to “震之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>四隤不安，兵革為患。掠我妻子，家復饑寒。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>震數四，《說文》隤，隊也，又壞也。司馬相如《上林賦》隤牆填。坎為破壞，故曰四隤不安。艮為兵革，坎為患，艮手為掠，震為子，伏巽為妻，故曰掠我妻子。艮為家，坎為寒，離虛，故曰饑寒。○隤，汲古作瀆，非，依宋元本。復，宋元本訛履。</p><h3 id="震之剝" tabindex="-1">震之剝 <a class="header-anchor" href="#震之剝" aria-label="Permalink to “震之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>喜來如雲，嘉福盈門。眾才君子，舉家蒙歡。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>此兼用《震》象。震為喜，坎為雲，震為嘉福，艮為門、為君子、為家，坎眾，故曰眾才。震樂，故曰蒙歡。○汲古第二句作第四句，第四句作第二句，今依宋元本。</p><h3 id="震之復" tabindex="-1">震之復 <a class="header-anchor" href="#震之復" aria-label="Permalink to “震之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>載金販狗，利棄我走。藏匿淵底，折毀為咎。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>詳《隨》之《革》。毀，宋本、汲古訛晦，元本訛悔，依局本。</p><h3 id="震之無妄" tabindex="-1">震之無妄 <a class="header-anchor" href="#震之無妄" aria-label="Permalink to “震之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>日中為市，各抱所有。交易貲賄，函珠懷寶，心悅歡喜。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《升》。</p><h3 id="震之大畜" tabindex="-1">震之大畜 <a class="header-anchor" href="#震之大畜" aria-label="Permalink to “震之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>日趨月步，周遍次舍。經歷致遠，無有難處。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>首句宋元本作月步日趨，茲依汲古。○乾為日，兌為月，震行，故日趨月步。震為周，艮為次舍。</p><h3 id="震之頤" tabindex="-1">震之頤 <a class="header-anchor" href="#震之頤" aria-label="Permalink to “震之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>陽明失時，陰凝為憂。主君哀泣，喪其元侯。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>艮為時，坤失，乾伏，故曰陽明失時、曰陰凝為憂。坤為憂也。震為主、為君，震為樂、為歌，震反為艮，故曰哀泣。震為諸侯、為長，故曰元侯。坤為喪。</p><h3 id="震之大過" tabindex="-1">震之大過 <a class="header-anchor" href="#震之大過" aria-label="Permalink to “震之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>年衰歲暮，精魂游去。形容銷枯，哀子相呼。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>乾為年歲，乾老，故曰衰暮。乾為精魂，大過死，故曰精魂游去。伏坤為形容，巽隕落，故銷枯。伏震為子，坤憂，故曰哀子。兌口，故曰呼，正反兌，故曰相呼。○哀，宋元本作喪，相作恩，依汲古。按：恩必是思之訛，喪子思呼亦通。</p><h3 id="震之坎" tabindex="-1">震之坎 <a class="header-anchor" href="#震之坎" aria-label="Permalink to “震之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>少無功績，老困失福。跂行徙倚，不知所立。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>艮為少，又為老，震為功績，坎困，故無功，故失福。震為行、為徙倚、為立，上下坎，故不知所立。○跂，汲古作跌，徙作跛，均依宋元本。</p><h3 id="震之離" tabindex="-1">震之離 <a class="header-anchor" href="#震之離" aria-label="Permalink to “震之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>持心瞿目，善數搖動。自東徂西，不安其處。散渙府藏，無有利得。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>伏坎為心，重離，故曰瞿目。《禮玉藻》視容瞿瞿，註：瞿瞿，驚遽不審貌。巽風，故搖動。離東，兌西，風散。艮為府藏，艮伏，故曰散渙府藏。巽為利，兌折故無。○瞿目，汲古作耀目，依宋元本。持心瞿目者，言驚懼不敢放逸也。</p><h3 id="震之鹹" tabindex="-1">震之鹹 <a class="header-anchor" href="#震之鹹" aria-label="Permalink to “震之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>齎貝贖狸，不聽我辭。繫於虎鬚，牽不得來。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《睽》。</p><h3 id="震之恆" tabindex="-1">震之恆 <a class="header-anchor" href="#震之恆" aria-label="Permalink to “震之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>老狼白獹，長尾大胡。前顛卻躓，無有利得。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>通《益》。艮為狼、為獹，《玉篇》韓獹，天下俊犬。艮為尾，與巽連，故曰長尾。艮為須，故為胡。胡，領肉下垂也。《詩豳風》狼跋其胡，《毛傳》老狼有胡，進則躐其胡，曰前顛後躓。乾為前，巽為顛、為利。卻，退也。坤喪，故無利。○胡，元本作狐，依宋本、汲古。卻，汲古作後，依宋元本。第四句汲古作岐人悅喜，非，依宋元本。</p><h3 id="震之遯" tabindex="-1">震之遯 <a class="header-anchor" href="#震之遯" aria-label="Permalink to “震之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>背地相憎，心志不同。如火與金，君猛臣慢，虎行兔伏。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>艮為背，伏坤為地、為心志。艮火，乾金，火爍金申不同，與相憎之故也。乾君，艮臣，艮虎，震為兔，震伏，故曰兔伏。○慢，汲古作懾，依宋元本。艮止，故曰慢。</p><h3 id="震之大壯" tabindex="-1">震之大壯 <a class="header-anchor" href="#震之大壯" aria-label="Permalink to “震之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>夏臺羑里，湯文厄處。鬼侯歠醢，岐人悅喜。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>詳《頤》之《復》。</p><h3 id="震之晉" tabindex="-1">震之晉 <a class="header-anchor" href="#震之晉" aria-label="Permalink to “震之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>牙櫱生達，螳螂啟戶。幽人利貞，鼓翼起舞。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>此亦兼用《震》象。震為萌芽、為生，故曰牙櫱生達。兌為斧、為螳蜋，艮為戶。震為人，互坎，故曰幽人，艮止，故曰利貞。震為翼、為鼓、為啟舞。○達，依《小畜》之《睽》校，各本皆作齒。</p><h3 id="震之明夷" tabindex="-1">震之明夷 <a class="header-anchor" href="#震之明夷" aria-label="Permalink to “震之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>烈女無夫，閔思苦憂。齊子無良，使我心愁。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>坤為女，震為夫，坤喪，故無夫。坤坎皆為思、為憂，伏巽為齊子，《詩齊風》齊子居止，《傳》文薑也，與其兄襄公通，故曰無良。坤為我，坎為心、為愁。</p><h3 id="震之家人" tabindex="-1">震之家人 <a class="header-anchor" href="#震之家人" aria-label="Permalink to “震之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>踐履危難，脫厄去患。入福喜門，見我大君。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>此用《震》象。互坎為危難，上震，故踐履危難。震出，故曰脫厄去患。震為福喜，互艮為門，伏巽，故曰入。震為君。○我，宋元本作悔，依汲古。</p><h3 id="震之睽" tabindex="-1">震之睽 <a class="header-anchor" href="#震之睽" aria-label="Permalink to “震之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>折臂接手，不能進酒。祈祀閑曠，神怒不喜。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>此仍用《震》象。互艮為臂、為手，坎為折、為矯輮，故曰折臂。接手，手反接也，即反縛也。《史記陳丞相世家》至即命武士縛信，反接之，又《前漢陳平傳》噲受詔，即反接檻車詣長安。坎為酒，艮止，故不能進。震為言，故曰祈祀。坎隱伏，故曰閑曠。言曠絕不祀也。震為神、為怒。</p><h3 id="震之蹇" tabindex="-1">震之蹇 <a class="header-anchor" href="#震之蹇" aria-label="Permalink to “震之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>蟻封穴戶，大雨將集。鵲起數鳴，牝雞嘆室。相薨雄父，未到在道。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>此仍用《震》象。伏巽為蟻，艮為穴戶，坎閉，故曰封。坎為雨、為集，震為鵲、為鳴。伏巽為雞，艮為室。末二句有訛字，故義未詳。按：漢明帝禱雨曾筮得此林，召沛獻王輔詮敘其義，王傳京易者也。○起數，汲古作數起，末作來，均依宋元本。雄父疑為雄犬，他林雄犬皆訛雄父是其證，汲古又作雄文，皆非。</p><h3 id="震之解" tabindex="-1">震之解 <a class="header-anchor" href="#震之解" aria-label="Permalink to “震之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>胡俗戎狄，太陰所積。固冰冱寒，君子不存。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>古者以戎狄為陰物，故易林皆以坤象戎狄。卦有重坎，坎為月，月者，太陰之精，故亦象戎狄。重坎，故曰積。坎為冰、為寒，艮為君子，上卦艮覆，故曰不存。○第三句元本冱作，汲古冰作冽，茲從宋本。者，冱之訛。《左傳》固陰冱寒。</p><h3 id="震之損" tabindex="-1">震之損 <a class="header-anchor" href="#震之損" aria-label="Permalink to “震之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>翕翕，消頹崩顛。滅其令名，身不得全。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>坤震皆為車，而震為聲，故曰翕翕，皆車聲也。坤消，二至四艮山覆，故曰崩顛。艮為名，震淑，故曰令名。坤喪，故滅其令名。坤為身，坤死，故不得全。○消，汲古訛稍，依宋元本。</p><h3 id="震之益" tabindex="-1">震之益 <a class="header-anchor" href="#震之益" aria-label="Permalink to “震之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>螟蟲為賊，害我稼穡。盡禾殫麥，秋無所得。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《革》。螟，宋元本作災，殫作單，均依汲古。</p><h3 id="震之夬" tabindex="-1">震之夬 <a class="header-anchor" href="#震之夬" aria-label="Permalink to “震之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>三鳥飛來，自我逢時。俱行先至，多得大利。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>伏艮為鳥，數三，故曰三鳥。艮為時，坤為我。</p><h3 id="震之姤" tabindex="-1">震之姤 <a class="header-anchor" href="#震之姤" aria-label="Permalink to “震之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>龍馬上山，絕無水泉。喉焦唇乾，渴不能言。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《訟》。絕，宋元本作焦，依汲古。焦唇，汲古作唇燋，能作可，皆依宋元本。</p><h3 id="震之萃" tabindex="-1">震之萃 <a class="header-anchor" href="#震之萃" aria-label="Permalink to “震之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>春生孳乳，萬物蕃熾。君子所集，禍災不至。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>伏震為春、為生，坤為孳乳、為萬物，坤為多，故曰蕃熾。艮為君子，坤為集、為禍災。○孳，汲古作子，依宋元本。至，宋元本作到，依汲古。</p><h3 id="震之升" tabindex="-1">震之升 <a class="header-anchor" href="#震之升" aria-label="Permalink to “震之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>王孫季子，相與為友。明允篤誠，升擢薦舉。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>震為王，艮為孫、為少男，故曰王孫季子。兌為朋友，言舜舉八元八愷也。</p><h3 id="震之困" tabindex="-1">震之困 <a class="header-anchor" href="#震之困" aria-label="Permalink to “震之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>六明並照，政紀有統。秦楚戰國，民受其咎。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>坎卦數六，互離，故曰六明並照。巽為紀、為統，兌西為秦，伏震為楚、為戰，上艮，故曰戰國。坎為眾、為民。六明，指六國。</p><h3 id="震之井" tabindex="-1">震之井 <a class="header-anchor" href="#震之井" aria-label="Permalink to “震之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>蝃蝀充側，佞人傾惑。女謁橫行，正道壅塞。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>詳《蠱》之《復》。傾，各本多作所，依《蠱》之《復》校。</p><h3 id="震之革" tabindex="-1">震之革 <a class="header-anchor" href="#震之革" aria-label="Permalink to “震之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>登昆侖，入天門。過糟邱，宿玉泉。同惠歡，見仁君。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>三字句，詳《比》之《姤》。</p><h3 id="震之鼎" tabindex="-1">震之鼎 <a class="header-anchor" href="#震之鼎" aria-label="Permalink to “震之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>體重難飛，未能越關，不離空垣。通《屯》。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>坤為體、為重，坎陷，故難飛。艮為關、為垣，坤虛，故曰空垣。○離空，宋元本作啻留，依汲古。</p><h3 id="震之震" tabindex="-1">震之震 <a class="header-anchor" href="#震之震" aria-label="Permalink to “震之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>枯匏不材，利以濟舟。渡逾河海，無有溺憂。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>艮為匏，伏巽，故曰枯匏。震為舟、為濟，伏巽為利，坎為河海、為憂，震出，故無有溺憂。○材，依顧校，各本皆作朽。顧雲國語枯匏不材於人。河，汲古作江，依宋元本。首句言枯匏雖無用，然以為舟可利濟也。</p><h3 id="震之艮" tabindex="-1">震之艮 <a class="header-anchor" href="#震之艮" aria-label="Permalink to “震之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>玄黃虺隤，行者勞疲。役夫憔悴，逾時不歸。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《革》。不，汲古作得，依宋元本。</p><h3 id="震之漸" tabindex="-1">震之漸 <a class="header-anchor" href="#震之漸" aria-label="Permalink to “震之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>孔德如玉，出於幽谷。飛上喬木，鼓其羽翼，輝光照國。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>詳《同人》之《坎》。○喬，汲古作高，依宋元本。</p><h3 id="震之歸妹" tabindex="-1">震之歸妹 <a class="header-anchor" href="#震之歸妹" aria-label="Permalink to “震之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>火雖熾，在吾後。寇雖眾，在吾右。身安吉，不危殆。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>詳《大有》之《需》。在吾，宋元本作出我，依汲古。吉，元本作居，依宋本、汲古。</p><h3 id="震之豐" tabindex="-1">震之豐 <a class="header-anchor" href="#震之豐" aria-label="Permalink to “震之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>旃裘羶國，文禮不飾。跨馬控弦，伐我都邑。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>詳《豫》之《需》。</p><h3 id="震之旅" tabindex="-1">震之旅 <a class="header-anchor" href="#震之旅" aria-label="Permalink to “震之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>被髪八十，慕德獻服。邊鄙不聳，以安王國。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>巽為髪，兌數十，艮數八，故曰被髪八十。伏震為德，坎為慕，此似言太公八十歸周也。艮為邊鄙、為國，伏震為王，故曰王國。</p><h3 id="震之巽" tabindex="-1">震之巽 <a class="header-anchor" href="#震之巽" aria-label="Permalink to “震之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>心得所好，口常欲笑。公孫蛾眉，雞鳴樂夜。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>伏坎為心、為夜，互兌為口，伏震為笑、為公，艮為孫，故曰公孫。巽為蛾、為雞鳴，艮為眉，坎為夜。《詩衛風》螓首蛾眉，皆狀美人之貌。《齊風》雞既鳴矣，《毛傳》雲雞鳴而夫人作，朝盈而君作，皆遵詩序思賢妃之說，茲雲樂夜，與下匪雞則鳴蒼蠅之聲意合，然則焦謂此詩為荒淫樂夜之詩，與毛序異。○夜，汲古作從，依宋元本。</p><h3 id="震之兌" tabindex="-1">震之兌 <a class="header-anchor" href="#震之兌" aria-label="Permalink to “震之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>馬能負乘，見邑之野。井獲粱稻，喜悅無咎。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>伏震為馬、為乘，艮為負、為邑、為野，巽為稻粱。兌悅。○能，汲古作西，依宋元本。粱，宋元木作粢，依汲古。</p><h3 id="震之渙" tabindex="-1">震之渙 <a class="header-anchor" href="#震之渙" aria-label="Permalink to “震之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>高飛視下，貪饕所在。腐臭為患，害於躬身。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>艮為飛，上巽，故曰高飛。艮為視，坎為下，巽為臭腐，坎為患害，艮為身。</p><h3 id="震之節" tabindex="-1">震之節 <a class="header-anchor" href="#震之節" aria-label="Permalink to “震之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>東行西步，失其次舍。乾侯野井，昭君喪居。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>詳《鼎》之《噬嗑》。君喪，汲古作公求，依宋元本。</p><h3 id="震之中孚" tabindex="-1">震之中孚 <a class="header-anchor" href="#震之中孚" aria-label="Permalink to “震之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>神鳥五彩，鳳凰為主。集於王谷，使年歲有。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>震為神，艮為鳥，巽卦數五，故曰神鳥五彩。震為主，艮為鳳凰，艮為谷，震為王，故曰五穀。《一統志》中條山有王官谷。盧思道《從駕玉照寺頌》：王谷蟲篆。震為年歲。○王，汲古作山，有作育，均依宋元本。</p><h3 id="震之小過" tabindex="-1">震之小過 <a class="header-anchor" href="#震之小過" aria-label="Permalink to “震之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>石門晨門，荷蕢食貧，遁世隱居，竟不逢時。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>詳《革》之《旅》。啟，宋元本作關，食作疾，均依汲古。</p><h3 id="震之既濟" tabindex="-1">震之既濟 <a class="header-anchor" href="#震之既濟" aria-label="Permalink to “震之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>嚙嚙，貧鬼相責。無有歡怡，一日九結。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>卦為三，兌形，兌為牙齒，故曰嚙嚙。兌為口，故相責。坎為鬼、為憂，故不怡。離為日，數九，故一日九結。</p><h3 id="震之未濟" tabindex="-1">震之未濟 <a class="header-anchor" href="#震之未濟" aria-label="Permalink to “震之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>白日揚光，雷車避藏。雲雨不行，各止其鄉。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《困》。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
